310	// The four state labels an open item may wear. An open item wearing none of them
311	// and no `needs-human` is off the state machine entirely — a torn label swap's
312	// leavings, which the janitor repairs (DESIGN §6.2, §11).
313	export const STATE_LABELS = [BLOCKED, READY, EXECUTING, AGENT];
314	
315	// The canonical statuses the same four decode to — what a reader tests against,
